'use strict';
document.addEventListener('DOMContentLoaded',function() {initThemeSwitcher();});function initThemeSwitcher() {const toggleContainer=document.getElementById('theme-toggle-container');const themeToggle=document.getElementById('theme-toggle');const body=document.body;
if (!toggleContainer||!themeToggle||!body) {return;}
function loadTheme() {const savedTheme=localStorage.getItem('portfolio-theme');if (savedTheme) {body.classList.remove('dark','light');body.classList.add(savedTheme);}else {
body.classList.add('dark');localStorage.setItem('portfolio-theme','dark');}
updateBulbAppearance();}
function saveTheme(theme) {try {localStorage.setItem('portfolio-theme',theme);}catch (e) {
}}
function toggleTheme(event) {const currentTheme=body.classList.contains('dark')?'dark':'light';const newTheme=currentTheme==='dark'?'light':'dark';
const toggleRect=toggleContainer.getBoundingClientRect();const x=toggleRect.left+toggleRect.width/2;const y=toggleRect.top+toggleRect.height/2;
document.documentElement.style.setProperty('--transition-x',`${x}px`);document.documentElement.style.setProperty('--transition-y',`${y}px`);
if (!document.startViewTransition) {
body.classList.remove('dark','light');body.classList.add(newTheme);saveTheme(newTheme);updateToggleAppearance();triggerThemeChangeEvent(newTheme);addClickAnimation();return;}
const transition=document.startViewTransition(()=>{body.classList.remove('dark','light');body.classList.add(newTheme);saveTheme(newTheme);updateToggleAppearance();});
transition.finished.then(()=>{triggerThemeChangeEvent(newTheme);}).catch(()=>{
});
addClickAnimation();}
function updateToggleAppearance() {
}
function addClickAnimation() {themeToggle.style.transform='scale(0.95)';setTimeout(function() {themeToggle.style.transform='';},150);}
function triggerThemeChangeEvent(theme) {const event=new CustomEvent('themeChanged',{detail:{theme:theme}});window.dispatchEvent(event);}
toggleContainer.addEventListener('click',function(e) {e.preventDefault();toggleTheme(e);});
toggleContainer.addEventListener('touchend',function(e) {e.preventDefault();toggleTheme(e);},{passive:false});
toggleContainer.setAttribute('tabindex','0');toggleContainer.setAttribute('role','switch');toggleContainer.setAttribute('aria-label','Toggle theme');toggleContainer.addEventListener('keydown',function(e) {if (e.key==='Enter'||e.key===' ') {e.preventDefault();toggleTheme(null);}});
loadTheme();}
function detectSystemTheme() {if (!window.matchMedia) return null;const darkModeQuery=window.matchMedia('(prefers-color-scheme: dark)');return darkModeQuery.matches?'dark':'light';}
function getAutoTheme() {const hour=new Date().getHours();
if (hour>=19||hour<7) {return'dark';}else {return'light';}}
const ThemeUtils={ getCurrentTheme:function() {return document.body.classList.contains('dark')?'dark':'light';}, setTheme:function(theme) {if (theme!=='dark'&&theme!=='light') {return;}document.body.classList.remove('dark','light');document.body.classList.add(theme);try {localStorage.setItem('portfolio-theme',theme);}catch (e) {}}, toggleTheme:function() {const currentTheme=this.getCurrentTheme();const newTheme=currentTheme==='dark'?'light':'dark';this.setTheme(newTheme);}, useSystemTheme:function() {const systemTheme=detectSystemTheme();if (systemTheme) {this.setTheme(systemTheme);}}, useAutoTheme:function() {const autoTheme=getAutoTheme();this.setTheme(autoTheme);}, onThemeChange:function(callback) {if (typeof callback!=='function') {return;}window.addEventListener('themeChanged',function(e) {callback(e.detail.theme);});}};
window.ThemeUtils=ThemeUtils;
if (window.matchMedia) {const darkModeQuery=window.matchMedia('(prefers-color-scheme: dark)');darkModeQuery.addEventListener('change',function(e) {
});}
function checkThemePersistence() {try {
localStorage.setItem('test','test');localStorage.removeItem('test');return true;}catch (e) {return false;}}checkThemePersistence();
function enableSmoothThemeTransition() {const body=document.body;
if (!body.classList.contains('theme-transition')) {body.classList.add('theme-transition');
const style=document.createElement('style');style.textContent=`
 .theme-transition,
 .theme-transition *,
 .theme-transition *::before,
 .theme-transition *::after {
 transition: background-color 0.3s ease,
 color 0.3s ease,
 border-color 0.3s ease,
 box-shadow 0.3s ease !important;
 }
 `;document.head.appendChild(style);}}
document.addEventListener('DOMContentLoaded',enableSmoothThemeTransition);
function animateThemeChange() {const overlay=document.createElement('div');overlay.style.cssText=`
 position: fixed;
 top: 0;
 left: 0;
 width: 100%;
 height: 100%;
 background: radial-gradient(circle, rgba(255,215,0,0.3) 0%, transparent 70%);
 pointer-events: none;
 z-index: 9997;
 opacity: 0;
 transition: opacity 0.3s ease;
 `;document.body.appendChild(overlay);
setTimeout(function() {overlay.style.opacity='1';},10);
setTimeout(function() {overlay.style.opacity='0';setTimeout(function() {document.body.removeChild(overlay);},300);},300);}
window.addEventListener('themeChanged',animateThemeChange);
function announceThemeChange(theme) {const announcement=document.createElement('div');announcement.setAttribute('role','status');announcement.setAttribute('aria-live','polite');announcement.classList.add('sr-only');announcement.textContent=`Theme switched to ${theme} mode`;document.body.appendChild(announcement);setTimeout(function() {document.body.removeChild(announcement);},1000);}
window.addEventListener('themeChanged',function(e) {announceThemeChange(e.detail.theme);});
(function() {
const savedTheme=localStorage.getItem('portfolio-theme');if (savedTheme) {document.documentElement.classList.add(savedTheme);}})();